import { expect, test } from "vitest";
import { conciseGeneratedTypeScript } from "../src/generated-typescript.js";

test("removes generated explanations while retaining directives and literals", () => {
	const source = [
		'// @generated by protoc-gen-es v2.12.1 with parameter "target=ts"',
		"/* eslint-disable */",
		"/**\n * @license Apache-2.0\n */",
		"/** Describes the generated record. */",
		"export type Record = {",
		"  /**",
		"   * Superseded by the current field.",
		"   * @deprecated",
		"   */",
		"  old: string;",
		"}",
		"// A generated explanation",
		'export const value = /*@__PURE__*/ String("// literal /* text */");',
		"export const pattern = /[/*]+/;",
		'export const template = `text // literal ${"/* literal */"} tail`;',
		"",
	].join("\n");
	const result = conciseGeneratedTypeScript(source);
	expect(result).toContain(
		'// @generated by protoc-gen-es v2.12.1 with parameter "target=ts"',
	);
	expect(result).toContain("/* eslint-disable */");
	expect(result).toContain("/**\n * @license Apache-2.0\n */");
	expect(result).toContain("/** @deprecated */");
	expect(result).toContain('/*@__PURE__*/ String("// literal /* text */")');
	expect(result).toContain("export const pattern = /[/*]+/;");
	expect(result).toContain('`text // literal ${"/* literal */"} tail`');
	expect(result).not.toContain("Describes the generated record");
	expect(result).not.toContain("Superseded by the current field");
	expect(result).not.toContain("A generated explanation");
	expect(conciseGeneratedTypeScript(result)).toBe(result);
});
